def human_duration(seconds: float | None) -> str:
    if seconds is None:
        return "unknown time"
    s = int(round(seconds))
    if s < 60:
        return f"{s} s"
    m = int(round(s / 60))
    if m < 60:
        return f"{m} min"
    return f"{m // 60} h {m % 60} min"


